// Runs the old MetaboliteDetector 3.3 spectrum functions on test spectra: SpectrumFunctions::getCentroidSpectrum<int,float>
// and Spectrum<int,float>::getBinnedSpectrum. Loaded with LD_PRELOAD into the old binary; it replaces main().
// Function addresses come from syms.inc, generated by run.sh.
//
// argv: app cases.txt out.txt. cases.txt: "C|B <n> <width|begin end maxdev>" then n lines "<mass> <value>".
// out.txt: "C|B <m>" then m lines "<mass> <value> [<fwhm>]" with the masses as float bits (hex).
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

// Layout of gcms::Spectrum<int, float> (from its constructor): +8 masses, +0x10 values;
// CentroidSpectrum adds +0x40 the fwhm vector.
using Values = std::vector<int>;
using Masses = std::vector<float>;
Masses* masses_of(void* s) { return *reinterpret_cast<Masses**>(static_cast<char*>(s) + 8); }
Values* values_of(void* s) { return *reinterpret_cast<Values**>(static_cast<char*>(s) + 0x10); }
std::vector<double>* fwhm_of(void* s) { return *reinterpret_cast<std::vector<double>**>(static_cast<char*>(s) + 0x40); }

uint32_t bits(float f) {
    uint32_t u;
    std::memcpy(&u, &f, 4);
    return u;
}

int spectrum_main(int argc, char** argv, char**) {
    if (argc != 3) {
        std::fprintf(stderr, "usage: cases.txt out.txt\n");
        return 2;
    }
    std::FILE* in = std::fopen(argv[1], "r");
    std::FILE* out = std::fopen(argv[2], "w");
    char kind;
    while (std::fscanf(in, " %c", &kind) == 1) {
        long n;
        double a = 0, b = 0, c = 0;
        std::fscanf(in, "%ld", &n);
        if (kind == 'B') std::fscanf(in, "%lf", &a);
        else std::fscanf(in, "%lf %lf %lf", &a, &b, &c);
        auto* masses = new Masses;
        auto* values = new Values;
        for (long i = 0; i < n; ++i) {
            double m;
            int v;
            std::fscanf(in, "%lf %d", &m, &v);
            masses->push_back(static_cast<float>(m));
            values->push_back(v);
        }
        alignas(16) static char spectrum[256];
        if (kind == 'B') {
            void* r = fn<void* (*)(const Values*, const Masses*, float)>(BINNED)(values, masses, static_cast<float>(a));
            std::fprintf(out, "B %zu\n", masses_of(r)->size());
            for (size_t i = 0; i < masses_of(r)->size(); ++i)
                std::fprintf(out, "%08x %d\n", bits((*masses_of(r))[i]), (*values_of(r))[i]);
        } else {
            fn<void (*)(void*, Values*, Masses*)>(SPECTRUM_CTOR)(spectrum, values, masses);
            void* r = fn<void* (*)(void*, const double&, const double&, const double&)>(CENTROID)(spectrum, a, b, c);
            std::fprintf(out, "C %zu\n", masses_of(r)->size());
            for (size_t i = 0; i < masses_of(r)->size(); ++i)
                std::fprintf(out, "%08x %d %.17g\n", bits((*masses_of(r))[i]), (*values_of(r))[i], (*fwhm_of(r))[i]);
        }
        std::fflush(out);
    }
    std::fclose(out);
    return 0;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(spectrum_main, argc, argv, init, fini, rtld_fini, stack_end);
}
